 solid #dfe8df;padding-top:17px}.shop-drawer-total div{display:flex;justify-content:space-between;color:#0a1f0a;font-weight:800;margin-bottom:14px}.shop-request{width:100%;border:0;border-radius:10px;background:#0f7140;color:#fff;padding:13px;cursor:pointer;font-weight:800}@media(max-width:1050px){.shop-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:800px){.shop-layout{grid-template-columns:1fr}.shop-filters{position:static}.shop-hero{padding:30px 24px}.shop-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.shop-grid{grid-template-columns:1fr}.shop-hero>*{position:relative;z-index:1}.shop-hero h1{font-weight:900;color:#fff!important;font-size:31px}}
.shop-layout{display:block}.shop-filters{position:static;display:grid;grid-template-columns:auto 2fr repeat(2,minmax(130px,1fr)) auto;gap:14px;margin-bottom:26px;padding:18px 20px}.shop-filters h3{margin:0;align-self:center}.shop-filter-group{border:0;padding:0;margin:0}.shop-reset{margin:0;align-self:end;white-space:nowrap}.shop-layout>section{width:100%}@media(max-width:800px){.shop-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.shop-filters h3{grid-column:1/-1}.shop-reset{align-self:center}}@media(max-width:520px){.shop-filters{display:block}.shop-filter-group{border-top:1px solid #e8eee8;padding-top:16px;margin-top:16px}.shop-reset{margin-top:18px}}.shop-grid{grid-template-columns:repeat(4,minmax(0,1fr))}@media(max-width:1180px){.shop-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:850px){.shop-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.shop-grid{grid-template-columns:1fr}}</style></head><body><?php include 'components/header.php'; ?><main class="shop-page"><div class="shop-container"><section class="shop-hero"><h1><strong>La</strong> librairie des normes, au service de la qualité.</h1><p>Explorez les références internationales ISO et les normes nationales disponibles auprès de l’ACONOQ. Choisissez vos documents, ajoutez-les au panier et envoyez votre demande de commande.</p><div class="shop-trust"><span><i class="fas fa-file-pdf"></i> Documents numériques</span><span><i class="fas fa-headset"></i> Assistance à la commande</span><span><i class="fas fa-shield-halved"></i> Références vérifiées</span></div></section><div class="shop-toolbar"><div><p class="section-tag" style="margin-bottom:6px;">Catalogue</p><h2>Normes <em>disponibles</em></h2></div><button class="shop-cart-button" id="open-cart"><i class="fas fa-shopping-basket"></i> Mon panier <span id="cart-count">0</span></button></div><div class="shop-layout"><aside class="shop-filters"><h3><i class="fas fa-sliders mr-2" style="color:#0f7140"></i>Filtrer<br>les normes</h3><div class="shop-filter-group"><label for="shop-search">Recherche</label><input id="shop-search" type="search" placeholder="Code ou titre…"></div><div class="shop-filter-group"><label for="shop-origin">Origine</label><select id="shop-origin"><option value="all">Toutes les origines</option><option>International</option><option>Nationale</option><option>Africaine</option></select></div><div class="shop-filter-group"><label for="shop-category">Catégorie</label><select id="shop-category"><option value="all">Toutes les catégories</option><option>Qualité</option><option>Environnement</option><option>Santé et sécurité</option><option>Sécurité de l’information</option><option>Agroalimentaire</option><option>Métrologie</option></select></div><div class="shop-filter-group"><label for="shop-format">Format</label><select id="shop-format"><option value="all">Tous les formats</option><option>PDF</option><option>Papier</option></select></div><button id="shop-reset" class="shop-reset"><i class="fas fa-rotate-left mr-1"></i> Réinitialiser les filtres</button></aside><section><div class="shop-results-head"><span class="shop-results-count" id="shop-count">Chargement…</span><select class="shop-sort" id="shop-sort"><option value="featured">Pertinence</option><option value="price-asc">Prix croissant</option><option value="price-desc">Prix décroissant</option><option value="name">Nom A–Z</option></select></div><div id="shop-grid" class="shop-grid"></div><div id="shop-pagination" class="shop-pagination"></div><div class="shop-note"><strong>À propos des prix et de la commande :</strong> les montants affichés sont indicatifs. La disponibilité, la version, le format et le montant final sont confirmés par l’ACONOQ avant paiement ou facturation.</div></section></div></div></main><div id="cart-backdrop" class="shop-drawer-backdrop"><aside class="shop-drawer"><div class="shop-drawer-head"><h2>Votre panier</h2><button id="close-cart" class="shop-close"><i class="fas fa-times"></i></button></div><div id="cart-list" class="shop-cart-list"></div><div class="shop-drawer-total"><div><span>Total indicatif</span><span id="cart-total">0 FCFA</span></div><button id="request-order" class="shop-request">Envoyer une demande de commande</button></div></aside></div><?php include 'components/footer.php'; ?><script>
(function(){const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));const fallback=[
{id:'iso-9001',code:'ISO 9001:2015',title:'Systèmes de management de la qualité — Exigences',origin:'International',category:'Qualité',format:'PDF',price:45000,icon:'fa-award',description:'Référence internationale pour établir et améliorer un système de management de la qualité.'},
{id:'iso-14001',code:'ISO 14001:2015',title:'Systèmes de management environnemental — Exigences',origin:'International',category:'Environnement',format:'PDF',price:45000,icon:'fa-leaf',description:'Cadre de management pour améliorer la performance environnementale.'},
{id:'iso-45001',code:'ISO 45001:2018',title:'Systèmes de management de la santé et sécurité au travail',origin:'International',category:'Santé et sécurité',format:'PDF',price:45000,icon:'fa-helmet-safety',description:'Exigences pour prévenir les blessures et améliorer la santé au travail.'},
{id:'iso-22000',code:'ISO 22000:2018',title:'Systèmes de management de la sécurité des denrées alimentaires',origin:'International',category:'Agroalimentaire',format:'PDF',price:50000,icon:'fa-utensils',description:'Exigences applicables aux organismes de la chaîne alimentaire.'},
{id:'iso-27001',code:'ISO/IEC 27001:2022',title:'Systèmes de management de la sécurité de l’information',origin:'International',category:'Sécurité de l’information',format:'PDF',price:55000,icon:'fa-shield-halved',description:'Cadre fondé sur les risques pour protéger les informations.'},
{id:'iso-17025',code:'ISO/IEC 17025:2017',title:'Compétence des laboratoires d’étalonnages et d’essais',origin:'International',category:'Métrologie',format:'PDF',price:50000,icon:'fa-flask',description:'Référence pour la compétence et le fonctionnement des laboratoires.'}
];let products=fallback.slice(),cart=JSON.parse(localStorage.getItem('aconoq-cart')||'[]'),currentPage=1;const pageSize=8;const grid=document.getElementById('shop-grid'),count=document.getElementById('shop-count'),search=document.getElementById('shop-search'),origin=document.getElementById('shop-origin'),category=document.getElementById('shop-category'),format=document.getElementById('shop-format'),sort=document.getElementById('shop-sort');function money(n){return n?new Intl.NumberFormat('fr-FR').format(n)+' FCFA':'Sur demande'}function imageFor(cat){const m={'Qualité':'https://images.pexels.com/photos/3861958/pexels-photo-3861958.jpeg?auto=compress&cs=tinysrgb&w=900','Environnement':'https://images.pexels.com/photos/3305/garden-apple-tree-countryside.jpg?auto=compress&cs=tinysrgb&w=900','Santé et sécurité':'https://images.pexels.com/photos/3768131/pexels-photo-3768131.jpeg?auto=compress&cs=tinysrgb&w=900','Agroalimentaire':'https://images.pexels.com/photos/1640777/pexels-photo-1640777.jpeg?auto=compress&cs=tinysrgb&w=900','Sécurité de l’information':'https://images.pexels.com/photos/60504/security-protection-anti-virus-software-60504.jpeg?auto=compress&cs=tinysrgb&w=900','Métrologie':'https://images.pexels.com/photos/2280571/pexels-photo-2280571.jpeg?auto=compress&cs=tinysrgb&w=900'};return m[cat]||'https://images.pexels.com/photos/5668473/pexels-photo-5668473.jpeg?auto=compress&cs=tinysrgb&w=900'}function renderPagination(totalPages){const p=document.getElementById("shop-pagination");if(totalPages<=1){p.innerHTML="";return}let h=`<button data-page="prev" ${currentPage===1?"disabled":""}><i class="fas fa-chevron-left"></i></button>`;for(let i=1;i<=totalPages;i++)h+=`<button data-page="${i}" class="${i===currentPage?"is-active":""}">${i}</button>`;h+=`<button data-page="next" ${currentPage===totalPages?"disabled":""}><i class="fas fa-chevron-right"></i></button>`;p.innerHTML=h}function render(){let q=search.value.toLowerCase().trim(),rows=products.filter(p=>(!q||(p.code+' '+p.title).toLowerCase().includes(q))&&(origin.value==='all'||p.origin===origin.value)&&(category.value==='all'||p.category===category.value)&&(format.value==='all'||p.format===format.value));if(sort.value==='price-asc')rows.sort((a,b)=>a.price-b.price);if(sort.value==='price-desc')rows.sort((a,b)=>b.price-a.price);if(sort.value==='name')rows.sort((a,b)=>a.title.localeCompare(b.title));const totalPages=Math.max(1,Math.ceil(rows.length/pageSize));if(currentPage>totalPages)currentPage=totalPages;const pageRows=rows.slice((currentPage-1)*pageSize,currentPage*pageSize);count.textContent=rows.length+' norme'+(rows.length>1?'s':'')+' trouvée'+(rows.length>1?'s':'');grid.innerHTML=pageRows.length?pageRows.map(p=>`<article class="shop-card"><div class="shop-card-cover"><img src="${imageFor(p.category)}" alt="Illustration ${esc(p.category)}" loading="lazy"><span class="shop-badge">${esc(p.origin)}</span></div><div class="shop-card-body"><span class="shop-code">${esc(p.code)}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="shop-card-meta"><span class="shop-price">${money(p.price)}<small>${esc(p.format)} · indicatif</small></span><span style="display:flex;align-items:center;gap:10px"><a class="shop-details" href="norme.php?code=${encodeURIComponent(p.code)}">Détails</a><button class="shop-add" data-id="${esc(p.id)}"><i class="fas fa-plus mr-1"></i>Ajouter</button></span></div></div></article>`).join(''):'<div class="shop-empty"><i class="fas fa-search text-3xl mb-3" style="color:#0f7140"></i><br>Aucune norme ne correspond à vos critères.</div>';renderPagination(totalPages)}function renderCart(){let total=0;document.getElementById('cart-count').textContent=cart.reduce((s,p)=>s+p.qty,0);const list=document.getElementById('cart-list');list.innerHTML=cart.length?cart.map(i=>{total+=i.price*i.qty;return `<div class="shop-cart-row"><div><strong>${esc(i.code)}</strong><span>${esc(i.title)} · ${i.qty} × ${money(i.price)}</span></div><button class="shop-remove" data-remove="${esc(i.id)}"><i class="fas fa-trash"></i></button></div>`}).join(''):'<div style="text-align:center;color:#687669;padding:40px 10px"><i class="fas fa-basket-shopping text-3xl mb-3" style="color:#0f7140"></i><br>Votre panier est vide.</div>';document.getElementById('cart-total').textContent=money(total);localStorage.setItem('aconoq-cart',JSON.stringify(cart))}function openCart(){document.getElementById('cart-backdrop').classList.add('is-open');renderCart()}function closeCart(){document.getElementById('cart-backdrop').classList.remove('is-open')}grid.addEventListener('click',e=>{const b=e.target.closest('.shop-add');if(!b)return;const p=products.find(x=>x.id===b.dataset.id),old=cart.find(x=>x.id===p.id);if(old)old.qty++;else cart.push({...p,qty:1});renderCart();b.innerHTML='<i class="fas fa-check mr-1"></i>Ajouté';setTimeout(()=>b.innerHTML='<i class="fas fa-plus mr-1"></i>Ajouter',900)});document.getElementById('cart-list').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;cart=cart.filter(x=>x.id!==b.dataset.remove);renderCart()});document.getElementById('open-cart').onclick=openCart;document.getElementById('close-cart').onclick=closeCart;document.getElementById('cart-backdrop').onclick=e=>{if(e.target.id==='cart-backdrop')closeCart()};document.getElementById('request-order').onclick=()=>{if(!cart.length){alert('Ajoutez au moins une norme à votre panier.');return}location.href='contact.php?objet=Demande%20de%20norme&panier='+encodeURIComponent(cart.map(x=>x.code).join(', '))};[search,origin,category,format,sort].forEach(x=>x.addEventListener('input',()=>{currentPage=1;render()}));document.getElementById('shop-pagination').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b)return;const total=Math.max(1,Math.ceil(products.length/pageSize));if(b.dataset.page==='prev')currentPage=Math.max(1,currentPage-1);else if(b.dataset.page==='next')currentPage=Math.min(total,currentPage+1);else currentPage=Number(b.dataset.page);render();window.scrollTo({top:document.getElementById('shop-grid').offsetTop-120,behavior:'smooth'})});document.getElementById('shop-reset').onclick=()=>{search.value='';origin.value='all';category.value='all';format.value='all';sort.value='featured';currentPage=1;render()};render();renderCart();if(location.hash==="#panier")openCart();document.addEventListener('DOMContentLoaded',function(){if(typeof supabaseClient!=='undefined'){supabaseClient.from('normes').select('id,code,titre,categorie,description,origine,statut').eq('statut','active').limit(30).then(({data})=>{if(!data?.length)return;const mapped=data.map(n=>({id:'db-'+n.id,code:n.code,title:n.titre,origin:n.origine||'Nationale',category:n.categorie||'Autres',format:'PDF',price:0,icon:'fa-book-open',description:n.description||'Norme référencée dans le catalogue ACONOQ.'}));products=[...mapped,...fallback.filter(f=>!mapped.some(m=>m.code===f.code))];render()}).catch(()=>{})}});})();</script></body></html>